import{_ as t,o as a,c as s,a5 as i}from"./chunks/framework.CsGesDJn.js";const m=JSON.parse('{"title":"Cases before implementation","description":"","frontmatter":{},"headers":[],"relativePath":"feature/content-task-workflow/workspace-task-real-data/test.md","filePath":"feature/content-task-workflow/workspace-task-real-data/test.md"}'),r={name:"feature/content-task-workflow/workspace-task-real-data/test.md"};function n(o,e,d,l,c,u){return a(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="cases-before-implementation" tabindex="-1">Cases before implementation <a class="header-anchor" href="#cases-before-implementation" aria-label="Permalink to &quot;Cases before implementation&quot;">​</a></h1><h2 id="demo-isolation-correction-cases-2026-10-16" tabindex="-1">Demo isolation correction cases (2026-10-16) <a class="header-anchor" href="#demo-isolation-correction-cases-2026-10-16" aria-label="Permalink to &quot;Demo isolation correction cases (2026-10-16)&quot;">​</a></h2><ul><li>Empty Workspace: Owner/Manager/Creator/Client GET returns empty, only count/find reads; no sample creation or assignee mutation.</li><li>Existing <code>Untitled post</code>: GET returns original Task ID and metadata unchanged, no extra Tasks or writes.</li><li>Seed compatibility: TaskSampleSeeder and explicit MongoDataSeeder remain available; never execute full seed on shared Atlas.</li><li>Migration rehearsal: all five scripts pass on a temporary Mongo clone before Atlas writes; final validator accepts legacy states and TODO/IN_REVIEW/FINISHED; Task document hashes unchanged.</li><li>Regression: Task details, assignment/start, Campaign deployment/closure, Request acceptance and content-writing/publishing tests remain green. No real Facebook posting or Campaign retry during verification.</li></ul><h3 id="verification-results-2026-10-16" tabindex="-1">Verification results (2026-10-16) <a class="header-anchor" href="#verification-results-2026-10-16" aria-label="Permalink to &quot;Verification results (2026-10-16)&quot;">​</a></h3><ul><li>Business <code>fix/task-demo-isolation</code>: clean build/package passed; 156 focused unit tests, zero failures/errors/skips. Covers reader (15), workflow service (37), dates (14), content-writing (22), Post service (3), seed guard (5), Campaign deployment/closure and Request services. No real Facebook calls or publishing consumer test in this suite.</li><li>Initial incremental test discovery failed with stale compiled classes (<code>NoClassDefFoundError: TaskListQuery</code>); clean Maven build resolved it without dependency changes.</li><li>Rehearsed all five existing Request/Task migrations on ephemeral Mongo with a bounded clone of affected data/metadata; schema guards passed and all five canonical Task states were inserted successfully on the local clone only.</li><li>After user-confirmed Business stop, Atlas APPLY passed against the identical source/script fingerprints. All 5 Task documents and approval history hashes unchanged; 1 Request normalized to V2 without changing its CANCELLED status/business data; legacy Task status enum retained. Post/Chat/Mail and other collection metadata unchanged.</li><li>Private before/after audit artifacts retained outside repositories under <code>.local-backups</code>; no init, bulk seed, Task backfill, deployment retry or external publication. Existing local inventory-script edits in Infrastructure left untouched.</li><li>Restart Business on the fixed branch, reload Web, then explicitly retry the approved Campaign. This real authenticated retry was NOT performed by the agent; schema readiness is verified, end-to-end deployment remains a user smoke test. Legacy Tasks without first-start evidence may remain mutation-locked by design.</li></ul><table tabindex="0"><thead><tr><th>Case</th><th>Expected</th></tr></thead><tbody><tr><td>API path and filters</td><td>Versioned endpoint; page/sort/status/type/search/campaignId forwarded</td></tr><tr><td>Mixed origins</td><td>Campaign and Request-generated Task IDs unchanged; manual Tasks retained; no duplicates</td></tr><tr><td>Scope/access</td><td>Every query constrained by workspaceId; nonmember rejected before Mongo/User reads; Client can list all</td></tr><tr><td>Filter/count</td><td>AND predicates before pagination; literal regex-special search; matching total; stable sort</td></tr><tr><td>Invalid filters</td><td>Unknown status/type, oversized search, malformed campaign ID rejected</td></tr><tr><td>Empty/error</td><td>Empty stays empty; 401/403/500/malformed body propagates to UI, no mock fallback</td></tr><tr><td>Display metadata</td><td>Names resolved in one bulk read; missing fields stay missing; no User secrets exposed</td></tr><tr><td>Four views</td><td>Same API rows/page/filter; five types + CANCELLED/DETAIL_IDENTIFIED not lost</td></tr><tr><td>Dates</td><td>Actual deadlines only; absent/invalid deadline unscheduled; no synthetic 2h/2day duration or venue</td></tr><tr><td>Read-only</td><td>No draggable status/date or fake priority; Task click actual summary and source links</td></tr><tr><td>Race</td><td>Older response cannot overwrite newly selected Workspace/filter; loading failure has retry</td></tr><tr><td>UI</td><td>vi/en, light/dark, responsive, keyboard dialog and controls; all views have pagination</td></tr></tbody></table><h2 id="results-2026-10-15" tabindex="-1">Results (2026-10-15) <a class="header-anchor" href="#results-2026-10-15" aria-label="Permalink to &quot;Results (2026-10-15)&quot;">​</a></h2><ul><li>Web: 109 tests across 11 Vitest files passed. New coverage verifies the versioned URL, filter forwarding, Spring Page.number normalization, 401/403/500 propagation, malformed/cross-Workspace responses, Task/source identity and real/missing deadlines.</li><li>Web type-check and production <code>npm.cmd run build</code> passed. Initial sandbox attempts failed on Vite child-process/native dependency restrictions; the normal build succeeded outside sandbox, without changing dependencies/config. Existing mockContentLibraryService static/dynamic import bundler warning remains outside scope.</li><li>Business: 69 focused tests passed (0 failures/errors/skips): WorkspaceTaskReaderTest 11, TaskServiceListTasksTest 3, CampaignTaskStoreTest 2, CampaignDeploymentProcessorTest 2, ContentRequestReviewServiceTest 13, ContentRequestServiceTest 23, AdminSecurityTest 15. These use mocks/test slices, not shared Mongo Atlas. The deploy-failure warning is an intentional failure-path fixture.</li><li>Scoped ESLint: no errors; two advisory warnings remain in useTasks for effect-driven fetch and sequence-ref cleanup. No lint rules were disabled. The stale-response browser case passed.</li><li>Playwright CLI: actual TaskListPage rendered in an isolated browser with fake session and mocked HTTP transport using Spring Page.number. Verified error/retry, original IDs/source link, all four views, cancelled/detail-identified rows, pagination, status/search forwarding, no-match state, delayed stale-response suppression, vi/en switching, keyboard Escape, and 375px light/dark screenshots. No real accounts/tokens were used and no shared backend was called by this harness.</li><li>No DB init/migration/seed/backfill, stash restore, commit or push. Gateway unchanged.</li></ul><h2 id="limits-next-local-check" tabindex="-1">Limits / next local check <a class="header-anchor" href="#limits-next-local-check" aria-label="Permalink to &quot;Limits / next local check&quot;">​</a></h2><p>Browser mocks do not prove Mongo Atlas data or real authenticated end-to-end access. Restart Business and refresh Web, then use an existing Workspace with successful Campaign deployment: compare Task IDs with Campaign tasks and accepted Content Request additions; test Owner/Manager/Creator/Client and another Workspace. If the API fails, the page now reports that error instead of inventing mock rows. Calendar/timeline visualize actual deadlines, not durations or publishing schedules; all views show the current paginated result only. Read-only status/date interactions remain intentional.</p>',10)])])}const h=t(r,[["render",n]]);export{m as __pageData,h as default};
